# - 0x4cf5f0: mov ecx, [0xae1050] -> thiscall, ret 8; 0x8cca10: push 0; push pessoa; mov ecx, [0xde1f54] -> ret 8;
# - 0x7c6830: push 1; push idioma (só o byte); push clube; push pessoa; mov ecx, [0xb74350] -> ret 0x10;
# - 0x5a0590: mov ecx, [0xae2a38] -> ret 4; 0x5986b0 e 0x597db0 (push cargo): ecx = finanças;
# - 0x417c10 (Date::operator=): push origem; push saída; lea ecx, destino -> ret 8;
# - 0x85e410: lea ecx, contrato local; 0x864550: push 0; push cargo; push -1; push 0; push clube; push pessoa; lea ecx,
#   contrato local -> ret 0x18.
